mid=sum(R(1,20)/(1+R(2*i+1,40)) for i in range(10))
row(1,c('a · Lower and upper area comparisons','Right rectangle gives1/3; endpoint trapezoid gives5/12','Left rectangle gives1/3; right rectangle gives5/12','Both bounds follow from equal rectangles'),n('b · Midpoint Rule with n=10',mid,tol=5e-7),why='For the decreasing convex curve1/t on[1,1.5], the right rectangle is strictly below the curve and the endpoint chord strictly above. Areas are(1/2)(2/3)=1/3 and(1/2)(1+2/3)/2=5/12. M₁₀=(1/20)Σ from i=0to9 of1/[1+(2i+1)/40]. The selections do not grade the area proof.',limited=True)
row(2,c('a · Tangent line, coordinates(t,y)','y=√2−t/2','y=√2+t/2','y=2−t/2'),n('a · Tangency coordinate t',s.sqrt(2)),n('b · Integral of the tangent from1to2',s.sqrt(2)-R(3,4)),c('b · Comparison','ln2 > √2−3/4 >0.66','ln2 < √2−3/4 <0.66','ln2 = √2−3/4'),why='Example1 has A=(1,1),D=(2,1/2),so the secant slope is−1/2. Set−1/t²=−1/2 to find t=√2; tangent y=√2−t/2. Strict convexity puts the curve above this tangent except at tangency. Integrating gives√2−3/4≈0.664214>0.66. Proof reasoning must still be written.',limited=True)
row(3,c('Area ordering for integer n≥2','Σ(k=2…n)1/k < ∫₁ⁿdt/t < Σ(k=1…n−1)1/k','Σ(k=1…n−1)1/k < ∫₁ⁿdt/t < Σ(k=2…n)1/k','Both sums equal the integral'),c('Reason for strictness','1/t is strictly decreasing on every unit subinterval','1/t is increasing','1/t is constant'),why='On[k,k+1],1/(k+1)<1/t<1/k except at endpoints. Integrate then sum k=1,…,n−1. The strict statement requires integer n≥2; at n=1 all three values are0. This checks the comparison, not a complete proof.',limited=True)
row(4,c('a · Bound for ln2','∫₁²dt/t < area of rectangle of height1 =1','∫₁²dt/t >1','∫₁²dt/t =1'),c('a · Bound for ln3','Convexity gives1/t≥1−t/4; ∫₁³(1−t/4)dt=1, with strict integral inequality','1/t≤1−t/4 throughout[1,3]','The right-endpoint rectangle has area greater than1'),c('b · Bound for e','2<e<3','1<e<2','3<e<4'),why='For ln2 the curve lies below1 on(1,2]. On[1,3] the tangent at2 is1−t/4 and lies below1/t except at2; its integral is1. Thus ln2<1<ln3; ln is increasing and ln e=1, so2<e<3. Written area proof remains separate.',limited=True)
row(5,c('Third logarithm law, x>0 and rational r','ln(x^r)=r ln x','ln(x^r)=(ln x)^r','ln(x^r)=ln x+r'),c('Derivative of ln(x^r)−r ln x','0','r/x','1/x'),n('Difference at x=1',0),why='By chain and rational power rules, d[ln(x^r)]/dx=(r x^(r−1))/x^r=r/x. Hence the difference has derivative0 on(0,∞), so is constant; evaluate at1 to obtain0. The source establishes rational r here before extending real powers. This checks proof milestones.',limited=True)
row(6,c('Second law in (11)','e^(x−y)=e^x/e^y','e^(x−y)=e^x−e^y','e^(x−y)=e^(y−x)'),c('Logarithm of the quotient','x−y','x/y','x+y'),why='Since e^x,e^y>0, the quotient law gives ln(e^x/e^y)=x−y=ln(e^(x−y)). Injectivity of ln proves equality for real x,y; written argument remains separate.',limited=True)
row(7,c('Third law in (11), rational r','(e^x)^r=e^(rx)','(e^x)^r=e^(x+r)','(e^x)^r=r e^x'),c('Logarithm of either side','rx','r+x','x^r'),why='Use the established rational-power logarithm law: ln((e^x)^r)=r ln(e^x)=rx=ln(e^(rx)); injectivity establishes the law. The source initially assumes rational r. Written proof remains separate.',limited=True)
row(8,c('Second law in (15), b>0','b^(x−y)=b^x/b^y','b^(x−y)=b^x−b^y','b^(x−y)=b^(y−x)'),c('Exponent after definition b^x=e^(x ln b)','(x−y)ln b = x ln b−y ln b','(x/y)ln b','ln b/(x−y)'),why='By the definition of real powers, b^(x−y)=e^((x−y)ln b)=e^(x ln b)/e^(y ln b)=b^x/b^y. Positivity of b makes all logarithms and denominators valid. Written proof remains separate.',limited=True)
row(9,c('Fourth law in (15), a,b>0','(ab)^x=a^x b^x','(ab)^x=a^x+b^x','(ab)^x=(a+b)^x'),c('Logarithm of the base product','ln(ab)=ln a+ln b','ln(ab)=ln a ln b','ln(ab)=ln a−ln b'),why='Write(ab)^x=e^(x ln(ab))=e^(x ln a+x ln b)=a^x b^x. Positivity of both bases is essential for the stated real-power definition. The choices check proof milestones.',limited=True)
row(10,c('a · Product law','log_b(xy)=log_b x+log_b y','log_b(xy)=log_b x log_b y','log_b(xy)=log_b x−log_b y'),c('b · Quotient law','log_b(x/y)=log_b x−log_b y','log_b(x/y)=log_b x/log_b y','log_b(x/y)=log_b x+log_b y'),c('c · Power law','log_b(x^y)=y log_b x','log_b(x^y)=(log_b x)^y','log_b(x^y)=log_b x+y'),why='Require b>0,b≠1; positive arguments x,y for a/b and x>0 with real exponent y for c. Put u=log_b x,v=log_b y and apply b^(u+v)=xy,b^(u−v)=x/y,(b^u)^y=x^y, then use the inverse log_b. The choices identify each conclusion but do not assess its full proof.',limited=True)
